use agmp_native_protocol::MinecraftPingResult;use anyhow::{bail,Context,Result};use sha1::Sha1;use sha2::{Digest,Sha256};use std::{fs,io::{Read,Write},net::{TcpListener,TcpStream,ToSocketAddrs},path::Path,time::{Duration,Instant}};use uuid::Uuid;use crate::sandbox::resolve;
pub fn port_available(host:&str,port:u16)->bool{TcpListener::bind((host,port)).is_ok()}
pub fn download_verified(root:&Path,url:&str,path:&str,hash:&str,hash_type:&str,max_bytes:u64)->Result<serde_json::Value>{let u=reqwest::Url::parse(url)?;if u.scheme()!="https"{bail!("HTTPS required")};let target=resolve(root,path,false)?;let parent=target.parent().ok_or_else(||anyhow::anyhow!("no parent"))?;fs::create_dir_all(parent)?;let limit=if max_bytes==0{536870912}else{max_bytes};let client=reqwest::blocking::Client::builder().timeout(Duration::from_secs(300)).user_agent("agmp-native/0.4.0").build()?;let mut resp=client.get(u).send()?;if !resp.status().is_success(){bail!("download HTTP {}",resp.status())};let temp=parent.join(format!(".agmp-{}.part",Uuid::new_v4()));let mut f=fs::File::create(&temp)?;let mut bytes=Vec::new();resp.take(limit+1).read_to_end(&mut bytes)?;if bytes.len() as u64>limit{let _=fs::remove_file(&temp);bail!("download exceeds maxBytes")};f.write_all(&bytes)?;f.flush()?;let actual=match hash_type.to_ascii_lowercase().as_str(){"sha1"=>{let mut h=Sha1::new();h.update(&bytes);hex::encode(h.finalize())},"sha256"=>{let mut h=Sha256::new();h.update(&bytes);hex::encode(h.finalize())},_=>bail!("unsupported hash type")};if actual.to_ascii_lowercase()!=hash.to_ascii_lowercase(){let _=fs::remove_file(&temp);bail!("hash mismatch")};fs::rename(&temp,&target)?;Ok(serde_json::json!({"path":target.to_string_lossy(),"bytes":bytes.len(),"hash":actual,"hashType":hash_type,"verified":true}))}
pub fn minecraft_ping(host:&str,port:u16,timeout_ms:u64)->Result<MinecraftPingResult>{let addr=format!("{host}:{port}").to_socket_addrs()?.next().ok_or_else(||anyhow::anyhow!("no address"))?;let timeout=Duration::from_millis(timeout_ms.clamp(100,30000));let start=Instant::now();let mut s=TcpStream::connect_timeout(&addr,timeout).context("connect MC")?;s.set_read_timeout(Some(timeout))?;s.set_write_timeout(Some(timeout))?;let mut h=Vec::new();write_vi(&mut h,0);write_vi(&mut h,0);write_vi(&mut h,host.len() as i32);h.extend_from_slice(host.as_bytes());h.extend_from_slice(&port.to_be_bytes());write_vi(&mut h,1);let mut frame=Vec::new();write_vi(&mut frame,h.len() as i32);frame.extend_from_slice(&h);s.write_all(&frame)?;s.write_all(&[1,0])?;s.flush()?;let _len=read_vi(&mut s)?;if read_vi(&mut s)?!=0{bail!("unexpected status packet")};let json_len=read_vi(&mut s)?;if json_len<=0||json_len>1048576{bail!("invalid status length")};let mut buf=vec![0u8;json_len as usize];s.read_exact(&mut buf)?;let v:serde_json::Value=serde_json::from_slice(&buf)?;Ok(MinecraftPingResult{reachable:true,latency_ms:start.elapsed().as_millis(),version:v.pointer("/version/name").and_then(|x|x.as_str()).unwrap_or_default().into(),protocol:v.pointer("/version/protocol").and_then(|x|x.as_i64()).unwrap_or_default(),players_online:v.pointer("/players/online").and_then(|x|x.as_i64()).unwrap_or_default(),players_max:v.pointer("/players/max").and_then(|x|x.as_i64()).unwrap_or_default(),description:v.pointer("/description/text").and_then(|x|x.as_str()).or_else(||v.get("description").and_then(|x|x.as_str())).unwrap_or_default().into()})}
fn write_vi(out:&mut Vec<u8>,mut v:i32){loop{if v&!0x7f==0{out.push(v as u8);return}out.push(((v&0x7f)|0x80)as u8);v=((v as u32)>>7)as i32}}fn read_vi(r:&mut impl Read)->Result<i32>{let mut v=0;for p in 0..5{let mut b=[0];r.read_exact(&mut b)?;v|=((b[0]&0x7f)as i32)<<(7*p);if b[0]&0x80==0{return Ok(v)}}bail!("VarInt too long")}
